export type CodeVisualKind = "directory-tree" | "quality-gallery" | "duplicate-gallery" | "color-channels" | "texture" | "pca" | "preprocessing";
export type DependencyReference = { label: string; target?: string; moduleId?: string };
export type FunctionTeaching = {
  purpose: string;
  problem: string;
  input: string;
  output: string;
  walkthrough: string[];
  next?: string;
  limitation?: string;
  math?: string;
  visual?: CodeVisualKind;
  dependencies?: { internal?: DependencyReference[]; external?: string[]; standard?: string[] };
};

const t = (purpose: string, problem: string, input: string, output: string, walkthrough: string[], extra: Partial<FunctionTeaching> = {}): FunctionTeaching => ({ purpose, problem, input, output, walkthrough, ...extra });

